import { useState, useEffect, useCallback } from 'react';
import { RoomService } from '@/services/room.service';
import { Room } from '@/types/room';
import { client, DB_ID, COLLECTIONS } from '@/lib/appwrite';

export function useRoom(roomId: string) {
    const [room, setRoom] = useState<Room | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchRoom = useCallback(async () => {
        if (!roomId) return;
        setLoading(true);
        try {
            const doc = await RoomService.get(roomId);
            setRoom(doc);
        } catch (err: any) {
            console.error('Fetch room failed:', err);
            setError(err.message || 'Failed to fetch room');
            setRoom(null);
        } finally {
            setLoading(false);
        }
    }, [roomId]);

    useEffect(() => {
        fetchRoom();

        const unsubscribe = client.subscribe(
            `databases.${DB_ID}.collections.${COLLECTIONS.ROOMS}.documents.${roomId}`,
            (response) => {
                // Real-time updates for single room
                if (response.events.includes('databases.*.collections.*.documents.*.update')) {
                    setRoom(response.payload as Room);
                } else if (response.events.includes('databases.*.collections.*.documents.*.delete')) {
                    setRoom(null); // Deleted
                    setError("Room was deleted");
                }
            }
        );

        return () => {
            unsubscribe();
        };
    }, [fetchRoom, roomId]); // Ensure useEffect dependencies are stable

    return {
        room,
        loading,
        error,
        refresh: fetchRoom
    };
}
