import { useState, useEffect, useCallback } from 'react';
import { MessageService } from '@/services/message.service';
import { Message, MessagePayload } from '@/types/message';
import { client, DB_ID, COLLECTIONS } from '@/lib/appwrite';
import { useSession } from './useSession';


export function useMessages(roomId: string) {
    const { session, isAuthenticated, user } = useSession();
    // ideally we check useRoomMembers to ensure they are active too, but checking session existence is step 1.
    // The UI handles the "isMember" logic before calling sendMessage ideally,
    // or we check it here. Let's trust session + UI for now for speed, but verify via service.

    const [messages, setMessages] = useState<Message[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);

    const fetchMessages = useCallback(async () => {
        if (!roomId) return;
        setLoading(true);
        try {
            const response = await MessageService.list(roomId);
            setMessages(response.documents);
        } catch (err: any) {
            console.error('Fetch messages failed:', err);
            setError(err.message || 'Failed to fetch messages');
        } finally {
            setLoading(false);
        }
    }, [roomId]);

    useEffect(() => {
        fetchMessages();

        const unsubscribe = client.subscribe(
            `databases.${DB_ID}.collections.${COLLECTIONS.MESSAGES}.documents`,
            (response) => {
                const payload = response.payload as Message;
                if (payload.room !== roomId) return;

                if (response.events.includes('databases.*.collections.*.documents.*.create')) {
                    setMessages(prev => [...prev, payload]);
                }
                // Usually don't update/delete messages in this MVP, but can add later
            }
        );

        return () => {
            unsubscribe();
        };
    }, [fetchMessages, roomId]);

    const sendMessage = async (payload: MessagePayload) => {
        // Rule #4: Active Session required
        if (!isAuthenticated || !session || !user) {
            throw new Error("Active session required to send message");
        }

        try {
            await MessageService.send(payload);
        } catch (err: any) {
            console.error('Send message failed:', err);
            throw err;
        }
    };

    return {
        messages,
        loading,
        error,
        sendMessage,
    };
}
