'use client';

import { useState, useRef, useEffect } from "react";
import { Message, MessageType } from "@/types/message";
import { Room } from "@/types/room";
import { Icons } from "@/components/icons";

interface ChatAreaProps {
    room: Room | null;
    messages: Message[];
    currentUser: string | null; // userId
    loading?: boolean;
    onSendMessage: (content: string, type: MessageType) => Promise<void>;
}

export default function ChatArea({ room, messages, currentUser, loading, onSendMessage }: ChatAreaProps) {
    const [inputText, setInputText] = useState("");
    const [sending, setSending] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(() => {
        scrollToBottom();
    }, [messages]);

    const handleSend = async () => {
        if (!inputText.trim()) return;
        setSending(true);
        try {
            await onSendMessage(inputText, "TEXT");
            setInputText("");
        } catch (error) {
            console.error("Failed to send message", error);
        } finally {
            setSending(false);
        }
    };

    if (loading) {
        return <div className="flex-1 flex items-center justify-center bg-surface-subtle dark:bg-surface-darkBase text-text-muted dark:text-text-darkMuted">Loading chat...</div>;
    }

    if (!room) {
        return <div className="flex-1 flex items-center justify-center bg-surface-subtle dark:bg-surface-darkBase text-text-muted dark:text-text-darkMuted">Select a room</div>;
    }

    return (
        <section className="flex-1 flex flex-col bg-surface-subtle dark:bg-surface-darkBase relative">
            {/* Header */}
            <div className="h-16 bg-surface-base dark:bg-surface-darkElevated border-b border-border-default dark:border-border-darkDefault px-6 flex items-center justify-between shrink-0">
                <div>
                    <h3 className="font-semibold text-text-primary dark:text-text-darkPrimary flex items-center gap-2">
                        <Icons.Hash className="w-4 h-4 text-brand-primary dark:text-brand-primaryDark" /> {room.name}
                        <span className={`text-xs px-2 py-0.5 rounded-full ${room.status === 'OPEN' ? 'bg-status-success/10 text-status-success dark:text-status-successDark' : 'bg-status-danger/10 text-status-danger dark:text-status-dangerDark'}`}>
                            {room.status}
                        </span>
                    </h3>
                    <p className="text-xs text-text-secondary dark:text-text-darkSecondary">ID: {room.$id}</p>
                </div>

                <div className="flex items-center gap-4 text-text-secondary dark:text-text-darkSecondary">
                    <button className="hover:text-text-primary dark:hover:text-text-darkPrimary transition"><Icons.Copy className="w-5 h-5" /></button>
                    <button className="hover:text-text-primary dark:hover:text-text-darkPrimary transition"><Icons.Info className="w-5 h-5" /></button>
                    <button className="hover:text-text-primary dark:hover:text-text-darkPrimary transition text-status-danger dark:text-status-dangerDark hover:text-red-600"><Icons.LogOut className="w-5 h-5" /></button>
                </div>
            </div>

            {/* Messages */}
            <div className="flex-1 px-8 py-6 space-y-6 overflow-y-auto">
                {messages.length === 0 && (
                    <div className="text-center text-text-muted dark:text-text-darkMuted text-sm mt-10">No messages yet. Say hello!</div>
                )}

                {messages.map((msg) => (
                    <MessageItem
                        key={msg.$id}
                        isMe={currentUser === msg.sender}
                        user={msg.sender} // In real app, we'd map ID to name
                        time={new Date(msg.$createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                        text={msg.content || ""}
                    />
                ))}
                <div ref={messagesEndRef} />
            </div>

            {/* Input */}
            <div className="border-t border-border-default dark:border-border-darkDefault p-4 bg-surface-base dark:bg-surface-darkElevated shrink-0">
                <div className="flex items-center gap-3">
                    <input
                        value={inputText}
                        onChange={(e) => setInputText(e.target.value)}
                        onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                        disabled={room.status !== 'OPEN'}
                        placeholder={room.status === 'OPEN' ? "Type your message..." : "Room is closed"}
                        className="flex-1 border border-border-default dark:border-border-darkDefault rounded-xl px-4 py-3 text-sm bg-surface-subtle dark:bg-surface-darkSubtle text-text-primary dark:text-text-darkPrimary focus:outline-none focus:ring-2 focus:ring-brand-primary dark:focus:ring-brand-primaryDark transition placeholder-text-muted dark:placeholder-text-darkMuted"
                    />
                    <button
                        onClick={handleSend}
                        disabled={!inputText.trim() || sending || room.status !== 'OPEN'}
                        className={`w-12 h-12 rounded-xl flex items-center justify-center text-white transition ${inputText.trim() && !sending ? 'bg-brand-primary hover:bg-brand-secondary dark:bg-brand-primaryDark' : 'bg-border-default dark:bg-surface-darkSubtle cursor-not-allowed'}`}
                    >
                        <Icons.Send className="w-5 h-5" />
                    </button>
                </div>
            </div>
        </section>
    );
}

function MessageItem({
    user,
    time,
    text,
    isMe
}: {
    user: string;
    time: string;
    text: string;
    isMe: boolean;
}) {
    return (
        <div className={`flex gap-4 ${isMe ? "flex-row-reverse" : ""}`}>
            <div className="w-10 h-10 rounded-full bg-brand-muted dark:bg-brand-mutedDark shrink-0 flex items-center justify-center text-brand-primary dark:text-brand-primaryDark text-xs font-bold">
                {user.substring(0, 2).toUpperCase()}
            </div>
            <div className={`flex flex-col ${isMe ? "items-end" : "items-start"}`}>
                <p className="text-sm font-medium text-text-primary dark:text-text-darkPrimary">
                    {isMe ? "You" : user} <span className="text-xs text-text-muted dark:text-text-darkMuted ml-1">{time}</span>
                </p>
                <div className={`mt-1 px-4 py-3 text-sm rounded-xl max-w-md break-words ${isMe ? "bg-brand-primary dark:bg-brand-primaryDark text-text-inverse" : "bg-surface-base dark:bg-surface-darkElevated border border-border-default dark:border-border-darkDefault text-text-primary dark:text-text-darkPrimary"}`}>
                    {text}
                </div>
            </div>
        </div>
    );
}
