'use client';

import { use, useEffect } from "react";
import ChatArea from "@/components/room/ChatArea";
import RoomDetails from "@/components/room/RoomDetails";
import { useRoom } from "@/hooks/useRoom";
import { useMessages } from "@/hooks/useMessages";
import { useRoomMembers } from "@/hooks/useRoomMembers";
import { useSession } from "@/hooks/useSession";
import { useRouter } from "next/navigation";
import { MessagePayload } from "@/types/message";
import { RoomService } from "@/services/room.service";

export default function RoomPage({ params }: { params: Promise<{ roomId: string }> }) {
    const { roomId } = use(params);
    const router = useRouter();

    // Hooks
    const { session, user, loading: sessionLoading } = useSession();
    const { room, loading: roomLoading, refresh: refreshRoom } = useRoom(roomId);
    const { messages, loading: messagesLoading, sendMessage } = useMessages(roomId);
    const { members, loading: membersLoading, addMember } = useRoomMembers(roomId);

    // Auth Protection
    useEffect(() => {
        if (!sessionLoading && !session) {
            router.push('/session');
        }
    }, [session, sessionLoading, router]);

    // Join Room logic (simplified)
    useEffect(() => {
        if (session && user && room && !membersLoading) {
            const isMember = members.some(m => m.user === user.userId && m.isActive);
            if (!isMember) {
                // Initial Join Logic
                addMember({
                    room: room.$id,
                    user: user.userId,
                    role: room.creatorId === user.userId ? 'CREATOR' : 'MEMBER'
                }).catch(console.error);
            }
        }
    }, [session, user, room, members, membersLoading, addMember]);

    const handleSendMessage = async (content: string, type: "TEXT" | "IMAGE" | "FILE") => {
        if (!user || !room) return;

        const payload: MessagePayload = {
            room: room.$id,
            sender: user.userId,
            type,
            content
        };
        await sendMessage(payload);
    };

    const handleCloseRoom = async () => {
        if (!room) return;
        if (confirm("Are you sure you want to close this room? It will be read-only.")) {
            try {
                await RoomService.close(room.$id);
                refreshRoom();
            } catch (e) {
                console.error(e);
                alert("Failed to close room");
            }
        }
    };

    if (sessionLoading) {
        return <div className="h-screen w-full flex items-center justify-center bg-surface-base dark:bg-surface-darkBase text-text-muted dark:text-text-darkMuted">Loading session...</div>;
    }

    if (!session) {
        return null; // Will redirect
    }

    return (
        <>
            <ChatArea
                room={room}
                messages={messages}
                currentUser={user?.userId || null}
                loading={roomLoading || messagesLoading || sessionLoading}
                onSendMessage={handleSendMessage}
            />
            <RoomDetails
                room={room}
                members={members}
                currentUserId={user?.userId || null}
                onCloseRoom={handleCloseRoom}
            />
        </>
    );
}
